<?php
namespace app\common\library;
use think\Db;use RuntimeException;use Throwable;
class IpaBindingService
{
    public static function compareCandidate(array $metadata,array $category){$reasons=[];$score=0;$authoritative=false;$public=self::normalizeUrl(isset($metadata['public_url'])?$metadata['public_url']:'');$bt1a=self::normalizeUrl(isset($category['bt1a'])?$category['bt1a']:'');if($public!==''&&$bt1a!==''&&$public===$bt1a){$score=100;$authoritative=true;$reasons[]='download_url_exact';}$package=trim((string)(isset($metadata['package_name'])?$metadata['package_name']:''));$name=trim((string)(isset($category['name'])?$category['name']:''));if($package!==''&&$name!==''&&$package===$name){$score+=20;$reasons[]='name_exact_hint';}$version=trim((string)(isset($metadata['package_version'])?$metadata['package_version']:''));$nickname=trim((string)(isset($category['nickname'])?$category['nickname']:''));if($version!==''&&$nickname!==''&&$version===$nickname){$score+=10;$reasons[]='version_exact_hint';}return ['score'=>min(100,$score),'authoritative'=>$authoritative,'reasons'=>$reasons];}
    public static function candidates($metadataId,$limit=20){$metadata=Db::name('ipa_metadata')->where('id',(int)$metadataId)->find();if(!$metadata)throw new RuntimeException('IPA metadata not found');$rows=[];$seen=[];if(!empty($metadata['public_url']))foreach((array)Db::name('category')->where('bt1a',$metadata['public_url'])->limit($limit)->select() as $row){$seen[(int)$row['id']]=true;$rows[]=$row;}if(!empty($metadata['package_name'])&&count($rows)<$limit)foreach((array)Db::name('category')->where('name',$metadata['package_name'])->limit($limit)->select() as $row)if(!isset($seen[(int)$row['id']])){$seen[(int)$row['id']]=true;$rows[]=$row;}$out=[];foreach($rows as $row){$match=self::compareCandidate($metadata,$row);$out[]=['category_id'=>(int)$row['id'],'name'=>$row['name'],'version'=>isset($row['nickname'])?$row['nickname']:'','bt1a'=>isset($row['bt1a'])?$row['bt1a']:'','score'=>$match['score'],'authoritative'=>$match['authoritative'],'reasons'=>$match['reasons']];}usort($out,function($a,$b){if($a['authoritative']!==$b['authoritative'])return $a['authoritative']?-1:1;return $b['score']-$a['score'];});return array_slice($out,0,max(1,(int)$limit));}
    public static function autoBindExactUrl($metadataId,$adminId=0){$candidates=self::candidates($metadataId,20);$exact=array_values(array_filter($candidates,function($x){return !empty($x['authoritative']);}));if(count($exact)!==1)throw new RuntimeException(count($exact)>1?'精确下载地址匹配到多条数据库记录，需要人工确认':'没有唯一精确下载地址候选');return self::bind($metadataId,(int)$exact[0]['category_id'],'exact_url',$adminId,true);}
    public static function bind($metadataId,$categoryId,$method='manual',$adminId=0,$requireAuthoritative=false){$metadataId=(int)$metadataId;$categoryId=(int)$categoryId;$metadata=Db::name('ipa_metadata')->where('id',$metadataId)->find();$category=Db::name('category')->where('id',$categoryId)->find();if(!$metadata)throw new RuntimeException('IPA metadata not found');if(!$category)throw new RuntimeException('Category record not found');if($metadata['parse_state']!=='success')throw new RuntimeException('只有已成功解析的 IPA 才能绑定');$match=self::compareCandidate($metadata,$category);if($requireAuthoritative&&!$match['authoritative'])throw new RuntimeException('自动绑定只允许精确下载地址匹配');$existingMeta=Db::name('ipa_binding')->where('metadata_id',$metadataId)->find();$existingCat=Db::name('ipa_binding')->where('category_id',$categoryId)->find();if($existingMeta&&(int)$existingMeta['category_id']!==$categoryId)throw new RuntimeException('该 IPA 已绑定其他数据库记录');if($existingCat&&(int)$existingCat['metadata_id']!==$metadataId)throw new RuntimeException('该数据库记录已绑定其他 IPA');if($existingMeta&&(int)$existingMeta['category_id']===$categoryId)return $existingMeta;$now=time();$idempotency=IpaFoundation::idempotencyKey('ipa_binding',['metadata_id'=>$metadataId,'category_id'=>$categoryId,'method'=>$method]);$operation=self::operationId();Db::startTrans();try{$bindingId=(int)Db::name('ipa_binding')->insertGetId(['category_id'=>$categoryId,'metadata_id'=>$metadataId,'source_key'=>$metadata['source_key'],'remote_path'=>$metadata['remote_path'],'remote_path_hash'=>$metadata['remote_path_hash'],'bundle_id'=>$metadata['bundle_id'],'md5'=>$metadata['md5'],'bind_method'=>$method,'confidence'=>$match['authoritative']?'exact':'derived','bound_by'=>(int)$adminId,'first_bound_at'=>$now,'last_seen_at'=>(int)$metadata['last_seen_at'],'createtime'=>$now,'updatetime'=>$now]);Db::name('ipa_operation_log')->insert(['operation_id'=>$operation,'idempotency_key'=>$idempotency,'operation_type'=>'binding_create','category_id'=>$categoryId,'metadata_id'=>$metadataId,'state'=>'success','before_json'=>'{}','after_json'=>json_encode(['binding_id'=>$bindingId,'method'=>$method,'match'=>$match],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),'admin_id'=>(int)$adminId,'started_at'=>$now,'finished_at'=>$now,'createtime'=>$now,'updatetime'=>$now]);Db::commit();return Db::name('ipa_binding')->where('id',$bindingId)->find();}catch(\Exception $e){Db::rollback();throw $e;}catch(Throwable $e){Db::rollback();throw $e;}}
    public static function unbind($bindingId,$adminId=0){$binding=Db::name('ipa_binding')->where('id',(int)$bindingId)->find();if(!$binding)throw new RuntimeException('Binding not found');$now=time();$idempotency=IpaFoundation::idempotencyKey('ipa_unbind',['binding_id'=>(int)$binding['id'],'category_id'=>(int)$binding['category_id'],'metadata_id'=>(int)$binding['metadata_id']]);Db::startTrans();try{Db::name('ipa_binding')->where('id',(int)$binding['id'])->delete();Db::name('ipa_operation_log')->insert(['operation_id'=>self::operationId(),'idempotency_key'=>$idempotency,'operation_type'=>'binding_remove','category_id'=>(int)$binding['category_id'],'metadata_id'=>(int)$binding['metadata_id'],'state'=>'success','before_json'=>json_encode($binding,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),'after_json'=>'{}','admin_id'=>(int)$adminId,'started_at'=>$now,'finished_at'=>$now,'createtime'=>$now,'updatetime'=>$now]);Db::commit();return true;}catch(\Exception $e){Db::rollback();throw $e;}catch(Throwable $e){Db::rollback();throw $e;}}
    public static function dashboard($limit=100){$bound=Db::name('ipa_binding')->count();$parsed=Db::name('ipa_metadata')->where('parse_state','success')->count();$rows=Db::name('ipa_metadata')->alias('m')->field('m.*,b.id binding_id,b.category_id,c.name category_name,c.nickname category_version,c.bt1a category_url')->join('ipa_binding b','b.metadata_id=m.id','LEFT')->join('category c','c.id=b.category_id','LEFT')->where('m.parse_state','success')->order('m.id','desc')->limit(max(1,min(500,(int)$limit)))->select();return ['stats'=>['bound'=>(int)$bound,'unbound'=>max(0,(int)$parsed-(int)$bound)],'rows'=>$rows];}
    protected static function normalizeUrl($url){$url=trim((string)$url);if($url==='')return '';return rtrim(str_replace(' ','%20',$url),'/');}
    protected static function operationId(){try{$b=random_bytes(16);}catch(\Exception $e){$b=md5(uniqid('',true),true);}$b[6]=chr((ord($b[6])&0x0f)|0x40);$b[8]=chr((ord($b[8])&0x3f)|0x80);$h=bin2hex($b);return substr($h,0,8).'-'.substr($h,8,4).'-'.substr($h,12,4).'-'.substr($h,16,4).'-'.substr($h,20);}
}
